scwin.fn_searchCode = async function() {
    /*
    00685-명의개서대행기관
    04774-PF구분코드	
    */
    dma_codReq.set("codeList", "TRANSSTK_AGNT_CD, TAX_TP_CD, ETF_REPLICA_METHD_TP_CD"); //코드정보 List
    const sbmOptions = {
        id: "sbm_listCodeValue",
        action: "/api/listing/common/code/list-code-value",
        method: "get",
        ref: "dma_codReq",
        target: "dlt_transstkAgntCd=body.TRANSSTK_AGNT_CD,"+
            "dlt_taxTpCd=body.TAX_TP_CD,"+
            "dlt_etfReplicaMethdTpCd=body.ETF_REPLICA_METHD_TP_CD",
        isProcessMsg: false
    };
    await $c.sbm.executeDynamic(sbmOptions);
    dlt_etfReplicaMethdTpCd.insertRow(0);
    cmb_ETF_REPLICA_METHD_TP_CD.setValue("");
};
scwin.fn_disableDistrMmDd = function() {
    //var ori_btnSave = btn_Save.src;
    //var ori_btn_Update = btn_Update.src;
    //var chk_btnSave = "btn_save.gif";
    //var chk_btn_Update = "btn_modify.gif";
