        //img_del.src = "../img/btn_arrowL.gif";
        img_Add.setDisabled(false);
        img_del.setDisabled(false);
    }
};
scwin.fn_getDistrBasMmDd = function() {
    if (dma_isuItemRes.get("bzProcsNo") != null) {
        for (var i = 1; i <= 12; i++) {
            if (dma_isuItemRes.get("earngDistrBasMmdd" + i) != "") {
                dlt_distrBasMmDd.insertRow();
                dlt_distrBasMmDd.setCellData(i-1, "earngDistrBasMmdd", dma_isuItemRes.get("earngDistrBasMmdd" + i));
            }
        }
        scwin.fn_DistrBasMmDdSetting();
    }
};
scwin.fn_DistrBasMmDdSetting = function(rPos) {
    if (dlt_distrBasMmDd.getTotalRow() > 0) {
        txb_DISTR_BAS_MMDD.setValue(dlt_distrBasMmDd.getCellData(0, "earngDistrBasMmdd"));
    }
};
scwin.fn_addDistrBasMmDd = function() {
    if (dlt_distrBasMmDd.getTotalRow() > 11) {
        $c.win.alert("[분배기준일]은  최대12개 입니다.");
        return false;
    } else {
        if (scwin.fn_dateCheck()) {
            grd_DISTR_BAS_MMDD.Redraw = false;
            dlt_distrBasMmDd.insertRow();
            dlt_distrBasMmDd.setCellData(dlt_distrBasMmDd.getRowCount()-1, "earngDistrBasMmdd", txb_DISTR_BAS_MMDD.getValue());
            grd_DISTR_BAS_MMDD.Redraw = true;
        }
    }
};
scwin.fn_delDistrBasMmDd = function() {
    if (dlt_distrBasMmDd.getTotalRow() < 1) {
        $c.win.alert("삭제할 [분배기준일]이 없습니다.");
        return false;
    } else {
        $c.cp.removeRow(dlt_distrBasMmDd, dlt_distrBasMmDd.getRowPosition());
        scwin.fn_DistrBasMmDdSetting(dlt_distrBasMmDd.getRowPosition());
        dlt_distrBasMmDd.getrowpos
    }
};
scwin.fn_SaveDistrBasMmDd = function() {
    for (var i = 1, j = 12; i <= j; i++) {
        dma_isuItemRes.set("earngDistrBasMmdd" + i, dlt_distrBasMmDd.getCellData(i-1, "earngDistrBasMmdd"));
    }
};
scwin.fn_dateCheck = function() {
    if (txb_DISTR_BAS_MMDD.getValue() != "") {
        if (txb_DISTR_BAS_MMDD.getValue().length == 4) {
            if (parseInt(txb_DISTR_BAS_MMDD.getValue().substring(0, 2), 10) < 13 && parseInt(txb_DISTR_BAS_MMDD.getValue().substring(0, 2), 10) > 0) {
                if (parseInt(txb_DISTR_BAS_MMDD.getValue().substring(2, 4), 10) < 32 && parseInt(txb_DISTR_BAS_MMDD.getValue().substring(2, 4), 10) > 0) {

                } else {
                    $c.win.alert("올바른 [분배기준일]을 입력하세요.");
                    txb_DISTR_BAS_MMDD.focus();
                    return false;
                }
            } else {
                $c.win.alert("올바른 [분배기준일]을 입력하세요.");
                txb_DISTR_BAS_MMDD.focus();
                return false;
            }
        } else {
            $c.win.alert("올바른 [분배기준일]을 입력하세요.");
            txb_DISTR_BAS_MMDD.focus();
            return false;
        }
        return true;
    } else {
        $c.win.alert("올바른 [분배기준일]을 입력하세요.");
        txb_DISTR_BAS_MMDD.focus();
        return false;
    }
};
