/**
 *	한글포함된 문자열 널값 및 최대길이 확인	*/
scwin.fn_checkValueNullMaxlength = function(vObj, vTitle) {
    var vMaxLength = vObj.maxLength;
    if (vObj.getValue() == "") {
        $c.win.alert(vTitle + "을 입력하세요.");
        vObj.focus();
        return false;
    }
    if ($c.str.getByteLength(vObj) > vMaxLength) {
        $c.win.alert("[" + vTitle + "] 입력길이가 " + vMaxLength + "자리를 초과할 수 없습니다.");
        vObj.focus();
        return false;
    }
    return true;
};



/*2010.07.30(2602) : 과세유형 추가*/
/**
 *	한글법인명 길이 확인
 */
scwin.fn_CheckForm = async function() {
    //$c.str.getByteLength(txb_COM_NM.getValue());
    if (cmb_SPOT_ISU_TRD_MKT_TP_CD.getValue() == "") {
        $c.win.alert("[시장구분]을 선택하세요.");
        return false;
    }
    if (cmb_SECUGRP_ID.getValue() == "") {
        $c.win.alert("[유가증권]을 선택하세요.");
        return false;
    }
    if (txb_ISU_CD.getValue() == "") {
        $c.win.alert("[종목]을 선택하세요.");
        img_SearchIsu.focus();
        return false;
    }
    if (txb_ISU_SRT_CD.getValue() == "") {
        $c.win.alert("[종목단축코드]항목값이  없습니다.");
        txb_ISU_SRT_CD.focus();
        return false;
    }
    if (scwin.TR_JOB == 'I') {
        if (await $c.lc.checkDoubleInput(txb_ISU_CD.getValue())) return false;
    }
    if (!scwin.fn_checkValueNullMaxlength(txb_COM_NM, "한글법인명")) return false;
    if (!scwin.fn_checkValueNullMaxlength(txb_COM_ABBRV, "한글법인약명")) return false;
    if (!scwin.fn_checkValueNullMaxlength(txb_COM_ENG_NM, "영문법인명")) return false;
    if (!scwin.fn_checkValueNullMaxlength(txb_COM_ENG_ABBRV, "영문법인약명")) return false;
    if (!scwin.fn_checkValueNullMaxlength(txb_ISU_KOR_NM, "한글종목명")) return false;
    if (!scwin.fn_checkValueNullMaxlength(txb_ISU_KOR_ABBRV, "한글종목약명")) return false;
    if (!scwin.fn_checkValueNullMaxlength(txb_ISU_ENG_NM, "영문종목명")) return false;
    if (!scwin.fn_checkValueNullMaxlength(txb_ISU_ENG_ABBRV, "영문종목약명")) return false;
    if (cmb_SPOT_ISU_TRD_MKT_TP_CD.getValue() == "1") {
        if (txb_ISUR_SYMBL.getValue() == "") {
            $c.win.alert("[영문법인심볼]을 입력하세요.");
            txb_ISUR_SYMBL.focus();
            return false;
        }
        if (await $c.lc.engSymblCheck(txb_ISUR_SYMBL.getValue())) {
            if (!$c.lc.chkEtfCorpSymblDoubleInput(txb_ISUR_SYMBL.getValue(), txb_ISUR_CD.getValue())) {
                $c.win.alert($c.lc.getGlbValue("MSG_SYMBL_DOUBLE_INPUT"));
                return false;
            }
        } else {
            txb_ISUR_SYMBL.focus();
            return false;
        }
        if (txb_ISU_ENG_SYMBL.getValue() == "") {
            $c.win.alert("[영문종목심볼]을 입력하세요.");
            txb_ISU_ENG_SYMBL.focus();
            return false;
        }
        if (await $c.lc.engSymblCheck(txb_ISU_ENG_SYMBL.getValue())) {
            if (!$c.lc.chkIsuSymblDoubleInput(txb_ISU_ENG_SYMBL.getValue(), txb_ISUR_CD.getValue())) {
                $c.win.alert($c.lc.getGlbValue("MSG_SYMBL_DOUBLE_INPUT"));
                return false;
            }
        } else {
            txb_ISU_ENG_SYMBL.focus();
            return false;
        }
    }
    if (txb_ZIPCD.getValue() == "") {
        $c.win.alert("[우편번호]를 선택하세요.");
        img_ZIPCD.focus();
        return false;
    }
    if (txb_LIST_NO.getValue() == "") {
        $c.win.alert("[상장번호]를 선택하세요.");
        txb_LIST_NO.focus();
        return false;
    }
    if (txb_CORP_TEL_NO.getValue() == "") {
        $c.win.alert("[법인전화번호]을 입력하세요.");
        txb_CORP_TEL_NO.focus();
        return false;
    }
    if (edt_LIST_DD.getValue() == "") {
        $c.win.alert("[상장일]을 입력하세요.");
        edt_LIST_DD.focus();
        return false;
    }
    if (scwin.vCurDate >= edt_LIST_DD.getValue()) {
        $c.win.alert("[상장일]을 현재일이후로 입력하세요.");
        edt_LIST_DD.focus();
        return false;
    }
