scwin.fn_setGridDataSet = function() {
    dlt_grdLPSaveList.removeAll();
    for (var i = 1; i <= dlt_grdLPList.getTotalRow(); i++) {
        var vLpMbrNo = dlt_grdLPList.getCellData(i-1, "lpMbrNo");
        if (vLpMbrNo != " " && vLpMbrNo != "") {
            dlt_grdLPSaveList.insertRow(i-1);
            dlt_grdLPSaveList.setCellData(i-1, "bzProcsNo", scwin.vBzProcsNo);
            dlt_grdLPSaveList.setCellData(i-1, "lpMbrNo", vLpMbrNo);
            dlt_grdLPSaveList.setCellData(i-1, "lpContrtDd", ''); //not null -> null
            dlt_grdLPSaveList.setCellData(i-1, "lpStrtDd", ''); //not null -> null
        }
    }
};
