        //scwin.vScrenTpCD = SCREN_PROCS_TP_CD_02;
        actionUrl = "/api/listing/lstproc/pf/new-listing/register";
    } else if (scwin.TR_JOB == 'U') {
        //scwin.vScrenTpCD = SCREN_PROCS_TP_CD_03;
        actionUrl = "/api/listing/lstproc/pf/new-listing/modify";
    } else if (scwin.TR_JOB == 'D') {
        //scwin.vScrenTpCD = SCREN_PROCS_TP_CD_04;
    }
    await scwin.fn_SaveDistrBasMmDd();
    await scwin.fn_setGridDataSet();
    // trs_Save.Action = $c.lc.fn_encodeNSession("/pf/PfLstinvstg.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + scwin.vScrenTpCD + "&method=saveNewListing");
    // trs_Save.KeyName = "toinb_dataid4";
    // trs_Save.KeyValue = "JSP(I:pInput=dts_IsuItem, I:pInputLP=dlt_grdLPSaveList)";
    // trs_Save.Parameters = "TRS_IDX=" + trsIdx + ",SECUGRP_ID=" + $c.stf.getObjectValue(cmb_SECUGRP_ID) + ",BZ_PROCS_NO=" + scwin.vBzProcsNo + ",ISUR_CD=" + dts_IsuItem.getCellData(1, "ISUR_CD") + ",LIST_BZ_TP_CD=" + LIST_BZ_TP_CD_810;
    // trs_Save.Post();

    //dma_isuReq.set("isuinfo", dma_isuinfo.getJSON())
    dma_isuItemRes.set("lpInfoList", dlt_grdLPSaveList.getAllJSON());
    debugger;
    const sbmOptions = {
        id: "sbm_save",
        action: actionUrl,
        method: "post",
        ref: "dma_isuItemRes",
        isProcessMsg: false
    };
    let res = await $c.sbm.executeDynamic(sbmOptions);

    scwin.trs_Save_OnSuccess();
};
