scwin.trs_Save_OnSuccess = async function() {
    //$c.lc.fn_alertMsg('S');
    if (scwin.TR_JOB == 'I') {
        $c.win.alert($c.stf.getMessageParam("MSG-A001", "저장"));
    } else {
        $c.win.alert($c.stf.getMessageParam("MSG-A001", "수정"));
    }

    scwin.fn_parentRefresh();
    if (scwin.TR_JOB == "U") {
        var parentWin = $c.win.getParent();
        parentWin.grd_List.setFocusedCell(scwin.rowPos, 0);
    }
    if (scwin.TR_JOB == "D") {
        // 삭제처리의 응답인 경우
        await $c.frame.CloseFrame();
    } else {
        dlt_distrBasMmDd.removeAll();
        scwin.fn_read_sync();
    }
    // 신규 저장이되면 값을 입력할수 있게  enable
    if (scwin.vBzProcsNo != "") btn_sim.setDisabled(false); // jackal_11.08.08

};
