scwin.init = async function() {
    txb_IDX_TOTAL_CD.hide();
    label_15.hide();
    cmb_SECUGRP_ID.hide();
    if ($c.session.getUserInfo("market") == "1") {
        scwin.pJsMarket = $c.session.getUserInfo("market");
    } else if ($c.session.getUserInfo("market") == "2") {
        scwin.pJsMarket = $c.session.getUserInfo("market");
    } else {
        scwin.pJsMarket = '1';
    }
    //$c.libRoundPanel.PanelToGroupBox(panel_Top);
    //$c.libRoundPanel.PanelToGroupBox(panel_Item);
    await scwin.fn_searchCode();
    await scwin.fn_searchLPCode();

    // dlt_grdLPSaveList.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=NEWLISTING_LP_INOUT";
    // dlt_grdLPSaveList.reset();
    // dlt_distrBasMmDd.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=ETF_DISTR_BAS_MMDD_INOUT";
    // dlt_distrBasMmDd.reset();

    var parentWin = $c.win.getParent();
    scwin.vBzProcsNo = parentWin.scwin.clickBzProcsNo;
    scwin.rowPos = parentWin.grd_List.getFocusedRowIndex();

    /* buttonSet의 초기화를 수행한다.  각 용도에 맞게 이미지ID와 onclick event시 수행할 function을 지정한다. */
    // buttonSet.setSaveInfo(btn_Save, fn_save); // 저장
    // buttonSet.setUpdateInfo(btn_Update, fn_update); // 수정
    // buttonSet.setDsclInfo(btn_Dscl, fn_dscl); // 안내문작성
    if (scwin.vBzProcsNo != "") {
        await scwin.fn_read_sync();
        //await scwin.fn_initLpAndDistrPayGridData("Y");
        txb_SearchIsuCd.setValue(dma_isuItemRes.get("isuCd"));
        txb_SearchIsuNm.setValue(dma_isuItemRes.get("isuKorNm"));
        cmb_SECUGRP_ID.setDisabled(true);
        btn_sim.setDisabled(false);
    } else {
        // dts_IsuItem.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=PF_ISU_NEWLISTING_INOUT";
        // dts_IsuItem.reset();
        // dts_IsuItem.insertRow();
        // dts_LP.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=NEWLISTING_LP_INOUT";
        // dts_LP.reset();
        cmb_SECUGRP_ID.setValue(parentWin.cmb_NEW_SECUGRP_ID.getValue()); //부모창에서 증권그룹값이 가져온다.
        cmb_SPOT_ISU_TRD_MKT_TP_CD.setValue(scwin.pJsMarket);
        await scwin.fn_initLpAndDistrPayGridData("N");

        // 신규 저장을 위해 창인 경우 disable
        btn_sim.setDisabled(true); // jackal_11.08.08		
        scwin.dts_IsuItem_OnLoadCompleted();
    }

    //scwin.fn_initLabel(cmb_SECUGRP_ID.getValue());    //사용할지 확인 필요
    scwin.fn_disableDistrMmDd();
};
